<script setup lang="ts">
import { ref,computed,onMounted,watch,toRaw } from 'vue'
import {useRoute,useRouter} from 'vue-router'
import MenuEditor from './MenuEditor.vue'
import Users from './Users.vue'
import AdminNavigation from './AdminNavigation.vue'
const route=useRoute(),router=useRouter()
import PrimeVue from 'primevue/config'
import Aura from '@primeuix/themes/aura'
import Button from 'primevue/button'
import InputText from 'primevue/inputtext'
import Editor from 'primevue/editor'
import { getCurrentInstance } from 'vue'
import { api,APIError,setCSRF,lang,language,t,sections,sectionName,type Organization,type Content,type List } from '../api'
const confirm=window.confirm.bind(window)
const app=getCurrentInstance()!.appContext.app
if(!app.config.globalProperties.$primevue)app.use(PrimeVue,{theme:{preset:Aura,options:{darkModeSelector:false}}})
interface User{id:number;organization_id:number;login:string;must_change:boolean;csrf:string}
const site=ref<{central:boolean;organization?:Organization}>();const user=ref<User>();const busy=ref(false);const error=ref('');const notice=ref('');const fieldErrors=ref<Record<string,string>>({});const login=ref('');const password=ref('');const current=ref('');const newPassword=ref('');const tab=ref(route.path.split('/')[2]||'news');const orgs=ref<Organization[]>([]);const orgTotal=ref(0);const orgPage=ref(1);const orgSearch=ref('');const selected=ref(0);const content=ref<Content[]>([]);const total=ref(0);const page=ref(1);const edit=ref<Content>();const orgEdit=ref<Organization>();const preview=ref<Content>();const editingLang=ref<'kk'|'ru'>('kk');const showPassword=ref(false)
const navigationDialog=ref<HTMLDialogElement>();const navigationToggle=ref<HTMLButtonElement>();
const workspace=computed(()=>!!user.value&&!user.value.must_change&&!showPassword.value)
function closeNavigation(){navigationDialog.value?.close();navigationToggle.value?.focus()}
function navigate(value:string){tab.value=value;closeNavigation()}
watch(workspace,()=>navigationDialog.value?.close())
const query=computed(()=>`?organization_id=${selected.value}`);const own=computed(()=>orgs.value.find(o=>o.id===selected.value));const central=computed(()=>user.value?.organization_id===0);const available=computed(()=>selected.value===0?sections.filter(s=>['news','documents'].includes(s[0])):sections.filter(s=>s[0]!=='contacts'))
async function run(action:()=>Promise<void>){busy.value=true;error.value='';fieldErrors.value={};notice.value='';try{await action()}catch(e){error.value=(e as Error).message;if(e instanceof APIError){fieldErrors.value=e.fields;if(e.status===401)user.value=undefined}}finally{busy.value=false}}
async function refreshUser(){user.value=await api<User>('/auth/me');setCSRF(user.value!.csrf);selected.value=user.value!.organization_id}
async function loadOrgs(){const data=await api<List<Organization>>(`/admin/organizations?page=${orgPage.value}&q=${encodeURIComponent(orgSearch.value)}`);orgs.value=data.items;orgTotal.value=data.total}
async function loadContent(){if(!user.value||user.value.must_change||['organizations','menu','users'].includes(tab.value))return;const data=await api<List<Content>>(`/admin/content${query.value}&kind=${tab.value}&page=${page.value}`);content.value=data.items;total.value=data.total}
async function initialize(){await refreshUser();if(!user.value?.must_change){await loadOrgs();await loadContent()}}
onMounted(()=>run(async()=>{site.value=await api('/site');try{await initialize()}catch(e){if(e instanceof APIError&&e.status===401)return;throw e}}))
async function signIn(){await api('/auth/login',{method:'POST',body:JSON.stringify({login:login.value,password:password.value})});current.value=password.value;password.value='';await initialize()}
async function changePassword(){const result=await api('/auth/password',{method:'POST',body:JSON.stringify({current:current.value,password:newPassword.value})});setCSRF(result.csrf);current.value='';newPassword.value='';showPassword.value=false;await initialize();notice.value=t('Құпиясөз өзгертілді','Пароль изменён')}
function startContent(c?:Content){edit.value=c?structuredClone(toRaw(c)):{id:0,organization_id:selected.value,kind:tab.value,published:false,position:0,translations:{kk:{title:'',body:''},ru:{title:'',body:''}},updated_at:'',schedule_date:new Date().toLocaleDateString('en-CA'),files:[]};for(const l of ['kk','ru'])edit.value.translations[l]??={title:'',body:''};preview.value=undefined;orgEdit.value=undefined}
function startOrg(o?:Organization){orgEdit.value=o?structuredClone(toRaw(o)):{id:0,slug:'',kind:'school',active:true,name:{kk:'',ru:''},profile:{},hidden_sections:[]};edit.value=undefined}
async function saveOrg(){const o=orgEdit.value!;orgEdit.value=await api(`/admin/organizations${o.id?'/'+o.id:''}`,{method:o.id?'PUT':'POST',body:JSON.stringify(o)});await loadOrgs();notice.value=t('Сақталды','Сохранено')}
async function saveContent(publish:boolean){const c=edit.value!;const saved=await api<Content>(`/admin/content${c.id?'/'+c.id:''}${query.value}`,{method:c.id?'PUT':'POST',body:JSON.stringify({...c,published:publish})});edit.value=saved;for(const l of ['kk','ru'])edit.value.translations[l]??={title:'',body:''};await loadContent();notice.value=publish?t('Жарияланды','Опубликовано'):t('Жоба сақталды','Черновик сохранён')}
async function showPreview(){preview.value=await api<Content>(`/admin/preview${query.value}`,{method:'POST',body:JSON.stringify(edit.value)})}
async function uploadFile(event:Event,logo=false){const input=event.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;await run(async()=>{if(!logo&&!edit.value?.id)await saveContent(false);const fd=new FormData();fd.append('file',f);fd.append('purpose',logo?'logo':'content');if(!logo)fd.append('content_id',String(edit.value!.id));const uploaded=await api(`/admin/uploads?organization_id=${logo?orgEdit.value!.id:selected.value}`,{method:'POST',body:fd});if(logo){orgEdit.value!.profile.logo=uploaded.id;await saveOrg()}else{await loadContent();edit.value=content.value.find(c=>c.id===edit.value!.id);if(edit.value)for(const l of ['kk','ru'])edit.value.translations[l]??={title:'',body:''}}});input.value=''}
async function switchOrg(){edit.value=undefined;orgEdit.value=undefined;page.value=1;tab.value='news';await loadContent()}
watch(()=>route.path,()=>{tab.value=route.path.split('/')[2]||'news'})
watch(tab,()=>run(async()=>{router.replace(tab.value==='news'?'/admin/':'/admin/'+tab.value);edit.value=undefined;orgEdit.value=undefined;preview.value=undefined;page.value=1;await loadContent()}))
watch(page,()=>run(loadContent))
</script>
<template><div class="admin-shell"><header class="site-header"><RouterLink to="/" class="brand"><img class="brand-mark" src="/shymkent-logo.svg" width="56" height="56" :alt="t('Шымкент қаласының логотипі','Логотип города Шымкент')"><span>{{site?.organization?(site.organization.name[lang]||site.organization.slug):t('Басқару панелі','Панель управления')}}<small>{{site?.organization?t('Мектеп басқару панелі','Админка школы'):'ШЫМКЕНТ · БІЛІМ'}}</small></span></RouterLink><div class="languages"><button @click="language('kk')" :aria-pressed="lang==='kk'">ҚАЗ</button><button @click="language('ru')" :aria-pressed="lang==='ru'">РУС</button></div><template v-if="user"><span>{{user.login}}</span><Button :label="t('Шығу','Выйти')" severity="secondary" :disabled="busy" @click="run(async()=>{await api('/auth/logout',{method:'POST'});user=undefined;edit=undefined;orgEdit=undefined})" /></template></header>
<main :class="{'admin-workspace':workspace}"><aside v-if="workspace" class="admin-sidebar"><p class="admin-nav-label">{{t('Басқару','Управление')}}</p><AdminNavigation :tab="tab" :central="central" :available="available" @navigate="navigate"/><RouterLink to="/" class="admin-site-link">{{t('Сайтқа өту ↗','Перейти на сайт ↗')}}</RouterLink></aside><div class="admin-content"><button v-if="workspace" ref="navigationToggle" class="admin-nav-toggle" aria-haspopup="dialog" aria-controls="admin-navigation" @click="navigationDialog?.showModal()">☰ {{t('Панель бөлімдері','Разделы панели')}}</button><dialog v-if="workspace" id="admin-navigation" ref="navigationDialog" class="admin-nav-dialog" :aria-label="t('Панель бөлімдері','Разделы панели')" @click="($event.target===navigationDialog)&&closeNavigation()" @cancel.prevent="closeNavigation()"><div class="admin-drawer-heading"><strong>{{t('Басқару','Управление')}}</strong><button autofocus @click="closeNavigation()" :aria-label="t('Жабу','Закрыть')">×</button></div><AdminNavigation :tab="tab" :central="central" :available="available" @navigate="navigate"/><RouterLink to="/" class="admin-site-link">{{t('Сайтқа өту ↗','Перейти на сайт ↗')}}</RouterLink></dialog><div v-if="error" class="notice" role="alert">{{error}}<ul v-if="Object.keys(fieldErrors).length"><li v-for="(v,k) in fieldErrors" :key="k">{{k}}: {{v}}</li></ul><Button v-if="user" :label="t('Қайталау','Повторить')" severity="secondary" @click="run(async()=>{await loadOrgs();await loadContent()})" /></div><p v-if="notice" class="success" role="status">{{notice}}</p><p v-if="busy" role="status">{{t('Орындалуда…','Выполняется…')}}</p>
<form v-if="!user" class="login-card" @submit.prevent="run(signIn)"><p class="eyebrow">ШЫМКЕНТ · БІЛІМ</p><h1>{{site?.organization?t('Мектеп әкімшісіне кіру','Вход в админку школы'):t('Орталық әкімшіге кіру','Вход в центральную панель')}}</h1><p>{{site?.organization?t('Осы мектептің әкімші тіркелгісін пайдаланыңыз','Используйте учётную запись администратора этой школы'):t('Орталық әкімші тіркелгісін пайдаланыңыз','Используйте учётную запись центрального администратора')}}</p><label>{{t('Логин','Логин')}}<InputText v-model="login" autocomplete="username" required /></label><label>{{t('Құпиясөз','Пароль')}}<InputText v-model="password" type="password" autocomplete="current-password" required /></label><Button type="submit" :label="t('Кіру','Войти')" :disabled="busy" /></form>
<template v-else><section v-if="user.must_change||showPassword" class="login-card"><h1>{{t('Құпиясөзді өзгерту','Смена пароля')}}</h1><p v-if="user.must_change">{{t('Жұмысты бастау үшін уақытша құпиясөзді өзгертіңіз','Для начала работы смените временный пароль')}}</p><form @submit.prevent="run(changePassword)"><label>{{t('Қазіргі құпиясөз','Текущий пароль')}}<InputText v-model="current" type="password" autocomplete="current-password" required /></label><label>{{t('Жаңа құпиясөз (12–72 байт)','Новый пароль (12–72 байта)')}}<InputText v-model="newPassword" type="password" autocomplete="new-password" required /></label><Button type="submit" :disabled="busy" :label="t('Өзгерту','Изменить')" /></form></section>
<template v-else><div class="admin-toolbar"><label v-if="central">{{t('Сайт','Сайт')}}<select v-model="selected" @change="run(switchOrg)"><option v-if="central" :value="0">{{t('Орталық портал','Центральный портал')}}</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name[lang]||o.slug}}</option></select></label><div v-else class="school-admin-scope"><strong>{{site?.organization?.name[lang]||own?.name[lang]}}</strong><small>{{t('Сіз тек өз мектебіңіздің деректерін басқарасыз','Вы управляете данными только своей школы')}}</small></div><Button v-if="own" :label="t('Ұйым баптаулары','Настройки организации')" severity="secondary" @click="startOrg(own)" /><Button severity="secondary" :label="t('Құпиясөз','Пароль')" @click="showPassword=true" /></div>

<MenuEditor v-if="tab==='menu'&&!orgEdit" :organization-id="selected" /><Users v-if="tab==='users'&&central&&!orgEdit" /><p v-if="['users','organizations'].includes(tab)&&!central" class="notice">{{t('Тек орталық әкімшіге қолжетімді','Доступно только центральному администратору')}}</p><section v-if="tab==='organizations'&&central&&!orgEdit"><div class="section-heading"><h1>{{t('Ұйымдар','Организации')}}</h1><Button :label="t('Ұйым қосу','Добавить организацию')" @click="startOrg()" /></div><form class="filters" @submit.prevent="run(async()=>{orgPage=1;await loadOrgs()})"><label>{{t('Атауы / нөмірі','Название / номер')}}<InputText v-model="orgSearch" /></label><Button type="submit" :label="t('Іздеу','Найти')" /></form><div class="table-scroll"><table><thead><tr><th>{{t('Атауы','Название')}}</th><th>{{t('Поддомен','Поддомен')}}</th><th>{{t('Күйі','Статус')}}</th><th></th></tr></thead><tbody><tr v-for="o in orgs" :key="o.id"><td>{{o.name[lang]||o.slug}}</td><td>{{o.slug}}</td><td>{{o.active?t('Белсенді','Активна'):t('Өшірілген','Отключена')}}</td><td><Button severity="secondary" :label="t('Материалдар','Материалы')" @click="run(async()=>{selected=o.id;await switchOrg()})" /> <Button severity="secondary" :label="t('Өзгерту','Редактировать')" @click="startOrg(o)" /></td></tr></tbody></table></div><p v-if="!orgs.length" class="empty">{{t('Ұйымдар жоқ','Организаций нет')}}</p><div v-if="orgTotal>20" class="pagination"><button :disabled="orgPage===1||busy" @click="run(async()=>{orgPage--;await loadOrgs()})">←</button><span>{{orgPage}} / {{Math.ceil(orgTotal/20)}}</span><button :disabled="orgPage*20>=orgTotal||busy" @click="run(async()=>{orgPage++;await loadOrgs()})">→</button></div></section>
<form v-if="orgEdit" class="editor-card" @submit.prevent="run(saveOrg)"><div class="section-heading"><h1>{{t('Ұйым баптаулары','Настройки организации')}}</h1><Button severity="secondary" :label="t('Жабу','Закрыть')" @click="orgEdit=undefined" /></div><div class="form-grid"><label v-for="l in ['kk','ru']" :key="l">{{l==='kk'?'Атауы · ҚАЗ':'Название · РУС'}}<InputText v-model="orgEdit.name[l]" /></label><label>{{t('Поддомен','Поддомен')}}<InputText v-model="orgEdit.slug" :disabled="!!orgEdit.id" required /></label><label>{{t('Түрі','Тип')}}<select v-model="orgEdit.kind" :disabled="!central"><option value="school">{{t('Мектеп','Школа')}}</option><option value="preschool">{{t('Балабақша','Дошкольная организация')}}</option></select></label><label v-for="key in ['address_kk','address_ru','summary_kk','summary_ru','phone','email','map_url']" :key="key">{{({address_kk:'Мекенжай · ҚАЗ',address_ru:'Адрес · РУС',summary_kk:'Қысқаша · ҚАЗ',summary_ru:'Описание · РУС',phone:t('Телефон','Телефон'),email:'Email',map_url:t('Карта сілтемесі','Ссылка на карту')} as Record<string,string>)[key]}}<InputText v-model="orgEdit.profile[key]" /></label></div><label v-if="central" class="check"><input type="checkbox" v-model="orgEdit.active">{{t('Белсенді ұйым','Активная организация')}}</label><Button type="submit" :label="t('Сақтау','Сохранить')" :disabled="busy" /><label v-if="orgEdit.id" class="upload-control">{{t('Логотип (JPEG, PNG, WebP)','Логотип (JPEG, PNG, WebP)')}}<input type="file" accept=".jpg,.jpeg,.png,.webp" :disabled="busy" @change="uploadFile($event,true)"></label><img v-if="orgEdit.profile.logo" :src="'/files/'+orgEdit.profile.logo+'?thumbnail=1'" alt="Логотип" width="100" height="100"></form>
<section v-else-if="!['organizations','menu','users'].includes(tab)&&!edit"><div class="section-heading"><h1>{{sectionName(tab)}}</h1><Button :label="t('Материал қосу','Добавить материал')" @click="startContent()" /></div><div class="table-scroll"><table><thead><tr><th>{{t('Атауы','Название')}}</th><th>{{t('Күйі','Статус')}}</th><th>{{t('Реті','Порядок')}}</th><th></th></tr></thead><tbody><tr v-for="c in content" :key="c.id"><td>{{c.translations[lang]?.title||t('Аударма жоқ','Нет перевода')}}</td><td><span class="tag">{{c.published?t('Жарияланған','Опубликован'):t('Жоба','Черновик')}}</span></td><td>{{c.position}}</td><td><Button severity="secondary" :label="t('Өзгерту','Редактировать')" @click="startContent(c)" /></td></tr></tbody></table></div><p v-if="!content.length" class="empty">{{t('Материалдар жоқ. Алғашқы материалды қосыңыз.','Материалов нет. Добавьте первый материал.')}}</p><div v-if="total>20" class="pagination"><button :disabled="page===1||busy" @click="page--">←</button><span>{{page}} / {{Math.ceil(total/20)}}</span><button :disabled="page*20>=total||busy" @click="page++">→</button></div></section>
<section v-if="edit" class="editor-card"><div class="section-heading"><h1>{{sectionName(edit.kind)}}</h1><Button severity="secondary" :label="t('Жабу','Закрыть')" @click="edit=undefined;preview=undefined" /></div><div class="tabs"><button @click="editingLang='kk'" :aria-pressed="editingLang==='kk'">ҚАЗ</button><button @click="editingLang='ru'" :aria-pressed="editingLang==='ru'">РУС</button></div><label>{{t('Тақырып','Заголовок')}}<InputText v-model="edit.translations[editingLang].title" /></label><label>{{t('Мәтін','Текст')}}</label><Editor v-model="edit.translations[editingLang].body" editorStyle="height: 260px"><template #toolbar><span class="ql-formats"><select class="ql-header"><option value="2"></option><option value="3"></option><option selected></option></select><button class="ql-bold" aria-label="Bold"></button><button class="ql-italic" aria-label="Italic"></button><button class="ql-list" value="ordered" aria-label="Ordered list"></button><button class="ql-list" value="bullet" aria-label="List"></button><button class="ql-link" aria-label="Link"></button><button class="ql-clean" aria-label="Clear formatting"></button></span></template></Editor><label v-if="edit.kind==='schedule'">{{t('Жаңарту күні','Дата обновления')}}<input type="date" v-model="edit.schedule_date" required></label><label>{{t('Көрсету реті','Порядок отображения')}}<input type="number" v-model.number="edit.position"></label><div class="actions"><Button :disabled="busy" severity="secondary" :label="t('Жобаны сақтау / жарияланымнан алу','Сохранить черновик / снять с публикации')" @click="run(()=>saveContent(false))" /><Button :disabled="busy" severity="secondary" :label="t('Алдын ала қарау','Предпросмотр')" @click="run(showPreview)" /><Button :disabled="busy" :label="t('Жариялау','Опубликовать')" @click="run(()=>saveContent(true))" /><Button v-if="edit.id" :disabled="busy" severity="danger" :label="t('Жою','Удалить')" @click="run(async()=>{if(confirm(t('Материалды жою керек пе?','Удалить материал?'))){await api('/admin/content/'+edit!.id,{method:'DELETE'});edit=undefined;await loadContent()}})" /></div><p class="quiet">{{t('Алдын ала қарау сервер тазартқан мәтінді көрсетеді.','Предпросмотр показывает очищенный сервером текст.')}}</p><label class="upload-control">{{edit.kind==='schedule'?t('PDF кестесін жүктеу / ауыстыру','Загрузить / заменить PDF расписания'):t('Файл қосу','Добавить файл')}}<input type="file" :accept="edit.kind==='schedule'?'.pdf':edit.kind==='gallery'?'.jpg,.jpeg,.png,.webp':'.jpg,.jpeg,.png,.webp,.pdf,.docx,.xlsx'" :disabled="busy" @change="uploadFile($event)"></label><div v-for="f in edit.files" :key="f.id" class="file-row"><a :href="'/files/'+f.id" target="_blank" rel="noopener">{{f.name}}</a><label v-for="l in ['kk','ru']" :key="l">{{l}}<InputText v-model="f.caption[l]" /></label><label>{{t('Реті','Порядок')}}<input type="number" v-model.number="f.position"></label><Button :disabled="busy" severity="secondary" :label="t('Сақтау','Сохранить')" @click="run(async()=>{await api('/admin/uploads/'+f.id,{method:'PUT',body:JSON.stringify({caption:f.caption,position:f.position})});notice=t('Сақталды','Сохранено')})" /><Button :disabled="busy" severity="danger" :label="t('Жою','Удалить')" @click="run(async()=>{if(confirm(t('Файлды жою керек пе?','Удалить файл?'))){await api('/admin/uploads/'+f.id,{method:'DELETE'});edit!.files=edit!.files.filter(x=>x.id!==f.id)}})" /></div><article v-if="preview" class="preview prose"><p class="eyebrow">{{t('АЛДЫН АЛА ҚАРАУ','ПРЕДПРОСМОТР')}}</p><h2>{{preview.translations[editingLang].title}}</h2><div v-html="preview.translations[editingLang].body"></div></article></section>
</template></template></div></main></div></template>
